import type { AsrProfile, AsrProfileId, AsrState } from './schema';

const KEY = 'tp_asr_profiles_v1';

let state: AsrState = (() => {
  try {
    const raw = localStorage.getItem(KEY);
    const parsed = raw ? JSON.parse(raw) as Partial<AsrState> : {};
    return { profiles: {}, ...parsed } as AsrState;
  } catch {
    return { profiles: {} } as AsrState;
  }
})();

const subs = new Set<(_s: AsrState) => void>();

function save() {
  try { localStorage.setItem(KEY, JSON.stringify(state)); } catch {}
  subs.forEach(fn => { try { fn(state); } catch {} });
  try { window.dispatchEvent(new CustomEvent('tp:asrChanged', { detail: state })); } catch {}
}

export const getAsrState = (): AsrState => state;

export function upsertProfile(p: AsrProfile) {
  state.profiles[p.id] = { ...p, updatedAt: Date.now() };
  if (!state.activeProfileId) state.activeProfileId = p.id;
  save();
}

export function setActiveProfile(id: AsrProfileId) {
  state.activeProfileId = id;
  save();
}

export function onAsr(fn: (_s: AsrState) => void) {
  subs.add(fn);
  return () => subs.delete(fn);
}

export function hasActiveAsrProfile(): boolean {
  try {
    // Prefer in-module state since this file is the canonical ASR store.
    if (
      state.activeProfileId ??
      (state as any).active_profile_id ??
      (state as any).profileId ??
      (state as any).profile_id ??
      (state as any).activeProfile ??
      (state as any).profile
    ) {
      return true;
    }

    // Defensive fallback for legacy/global integration points.
    const anyStore: any = (globalThis as any).__asrStore ?? undefined;
    const w: any = window as any;
    const externalState =
      (typeof w.getAsrState === 'function' ? w.getAsrState() : undefined) ??
      (typeof anyStore?.getState === 'function' ? anyStore.getState() : undefined) ??
      undefined;

    if (!externalState) return false;

    return Boolean(
      externalState.activeProfileId ??
      externalState.active_profile_id ??
      externalState.profileId ??
      externalState.profile_id ??
      externalState.activeProfile ??
      externalState.profile
    );
  } catch {
    return false;
  }
}

// storage-sync so Display picks up changes:
try {
  window.addEventListener('storage', (e: StorageEvent) => {
    try {
      if (e.key === KEY && e.newValue) {
        const next = JSON.parse(e.newValue) as AsrState;
        state = { ...next, profiles: next?.profiles || {} } as AsrState;
        subs.forEach(fn => { try { fn(state); } catch {} });
      }
    } catch {}
  });
} catch {}
